/bin/bash -lc "uv run --no-sync --project /home/horde/apps/newton-live-mcp python - <<'PY'
import numpy as np, cvxpy as cp
for p in ['training.npz','training-regressor.npz']:
 d=np.load(p);print(p, [(k,d[k].shape,str(d[k].dtype)) for k in d.files]);
 if 'episode_ids' in d: print('episodes',d['episode_ids'],'offsets',d['episode_offsets']); print('ranges', {k:(d[k].min(0).tolist(),d[k].max(0).tolist()) for k in ['q','qd','qdd','tau']})
r=np.load('training-regressor.npz');a=r['A'];b=r['b'];u,s,v=np.linalg.svd(a,full_matrices=False);x=np.linalg.lstsq(a,b,rcond=1e-5)[0]
print('solvers',cp.installed_solvers());print('singular',s.tolist());print('LS_RMSE',np.mean((a@x-b).reshape(-1,7)**2,axis=0)**.5);print('LS_jointpars',x[70:])
PY"

